// --- Sweep combinatorics tests ---

/// Product mode with defaults produces many tasks (6 u-values * default seed = 6 tasks)
#[test]
fn product_mode_produces_tasks() {
    let config = default_config();
    let tasks = build_all_scf_tasks(&config).unwrap();
    // Default: 6 u-values (0.0..5.0), no kpoints/cutoffs by default -> 6 tasks
    assert_eq!(tasks.len(), 6);
}

/// Product mode with explicit u-values, kpoints, and cutoffs produces Cartesian product
#[test]
fn product_mode_cartesian_product() {
    let config = SweepConfig::parse_from([
        "test",
        "--u-values", "0.0,1.0,2.0",
        "--kpoints", "8x8x8,6x6x6",
        "--cutoffs", "300,500,800",
        "--sweep-mode", "product",
    ]);
    let tasks = build_all_scf_tasks(&config).unwrap();
    // 3 u * 2 k * 3 c = 18 tasks
    assert_eq!(tasks.len(), 18);
}

/// Pairwise mode produces zipped tasks
